import os
import secrets
import urllib.parse
import webbrowser
from http.server import BaseHTTPRequestHandler, HTTPServer

import requests


AUTH0_DOMAIN = os.environ["AUTH0_DOMAIN"]
AUTH0_CLIENT_ID = os.environ["AUTH0_CLIENT_ID"]
AUTH0_CLIENT_SECRET = os.environ["AUTH0_CLIENT_SECRET"]
AUTH0_CALLBACK_URL = os.environ.get("AUTH0_CALLBACK_URL", "http://127.0.0.1:8765/callback")
AUTH0_AUDIENCE = os.environ.get("AUTH0_AUDIENCE")
AUTH0_SCOPE = os.environ.get("AUTH0_SCOPE", "openid profile email")
AUTH0_CONNECTION = os.environ.get("AUTH0_CONNECTION")


def build_authorization_url(state, nonce):
    params = {
        "response_type": "code",
        "client_id": AUTH0_CLIENT_ID,
        "redirect_uri": AUTH0_CALLBACK_URL,
        "scope": AUTH0_SCOPE,
        "state": state,
        "nonce": nonce,
    }
    if AUTH0_AUDIENCE:
        params["audience"] = AUTH0_AUDIENCE
    if AUTH0_CONNECTION:
        params["connection"] = AUTH0_CONNECTION
    return f"https://{AUTH0_DOMAIN}/authorize?{urllib.parse.urlencode(params)}"


def exchange_code_for_tokens(code):
    token_url = f"https://{AUTH0_DOMAIN}/oauth/token"
    data = {
        "grant_type": "authorization_code",
        "client_id": AUTH0_CLIENT_ID,
        "client_secret": AUTH0_CLIENT_SECRET,
        "code": code,
        "redirect_uri": AUTH0_CALLBACK_URL,
    }
    resp = requests.post(token_url, json=data, timeout=30)
    resp.raise_for_status()
    return resp.json()


class CallbackHandler(BaseHTTPRequestHandler):
    expected_state = None
    auth_result = {}

    def do_GET(self):
        parsed = urllib.parse.urlparse(self.path)
        if parsed.path != urllib.parse.urlparse(AUTH0_CALLBACK_URL).path:
            self.send_error(404)
            return

        query = urllib.parse.parse_qs(parsed.query)
        if "error" in query:
            self._send_text(f"Login failed: {query.get('error', ['unknown'])[0]}")
            self.auth_result = {"error": query.get("error", ["unknown"])[0]}
            return

        code = query.get("code", [None])[0]
        state = query.get("state", [None])[0]

        if not code or not state or state != self.expected_state:
            self._send_text("Invalid or missing authorization response.")
            self.auth_result = {"error": "invalid_response"}
            return

        try:
            tokens = exchange_code_for_tokens(code)
            self.auth_result = {"tokens": tokens}
            self._send_text("Login successful. You can close this window.")
        except Exception as exc:
            self.auth_result = {"error": str(exc)}
            self._send_text(f"Token exchange failed: {exc}")

    def log_message(self, format, *args):
        return

    def _send_text(self, text):
        body = text.encode("utf-8")
        self.send_response(200)
        self.send_header("Content-Type", "text/plain; charset=utf-8")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)


def start_oauth_login():
    state = secrets.token_urlsafe(32)
    nonce = secrets.token_urlsafe(32)

    CallbackHandler.expected_state = state
    CallbackHandler.auth_result = {}

    url = build_authorization_url(state, nonce)

    server = HTTPServer(("127.0.0.1", 8765), CallbackHandler)
    webbrowser.open(url)

    while not CallbackHandler.auth_result:
        server.handle_request()

    return CallbackHandler.auth_result


if __name__ == "__main__":
    result = start_oauth_login()
    print(result)
